scripts.preRequest:
const now = new Date();
const yyyy = now.getFullYear();
const mm = String(now.getMonth() + 1).padStart(2, '0');
const dd = String(now.getDate()).padStart(2, '0');
const hh = String(now.getHours()).padStart(2, '0');
const mi = String(now.getMinutes()).padStart(2, '0');
const code = `admin-${yyyy}-${mm}-${dd}-${hh}-${mi}`;
rq.environment.set("admin_code", code);

scripts.postResponse:
rq.test("Successful POST request", function () {
    rq.expect(rq.response.code).to.be.oneOf([200, 201]);
});

var jsonData = JSON.parse(rq.response.text());
rq.environment.set("integrationId", jsonData.id);
